mapper.select:
SELECT 
FROM notification_inbox_message
WHERE account_id = #{accountId}
AND id < #{beforeId}
ORDER BY id DESC
LIMIT #{limit}

mapper.update:
UPDATE notification_inbox_message
SET read_at = #{readAt}, version = version + 1
WHERE id = #{inboxMessageId}
  AND account_id = #{accountId}
  AND read_at IS NULL
  AND version = #{expectedVersion}
